"""Compare completed fixed evaluations to archived v3 lambda=.1 without retuning."""
import json,csv,hashlib
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs/v3_generalization_20261009'
OLD=ROOT/'outputs/data_efficiency/v3_baseline_p0_20261008_r1'
from analyze_v3_study import write_csv,table
results=json.loads((OUT/'results.json').read_text());lookup={(r['model'],r['seed']):r for r in results['rows']}
protocol=json.loads((OUT/'protocol.json').read_text());evidence=[];rows=[]
for seed in [42,7,123]:
 oldbase=OLD/f'runs/ratio_10/lead7_seed{seed}/baseline';oldphys=OLD/f'runs/ratio_10/lead7_seed{seed}/p0'
 b=json.loads((oldbase/'test_metrics.json').read_text());p=json.loads((oldphys/'test_metrics.json').read_text())
 for arm,path in [('baseline',oldbase),('physics_only',oldphys)]:
  newrow=next(r for r in protocol['rows'] if r['seed']==seed and r['arm']==arm)
  oc=json.loads((path/'config.json').read_text());nc=json.loads(Path(newrow['config_file']).read_text())
  diffs={k:[oc['settings'].get(k),v] for k,v in nc['settings'].items() if oc['settings'].get(k)!=v}
  equal={k:oc[k]==nc[k] for k in ['manifest_sha256','stats','split_sha256','tensor_fingerprints','shared_initial_sha256','parameters','evaluation_mask_cells']}
  ev=dict(seed=seed,arm=arm,old_run=str(path),new_run=newrow['run_dir'],settings_differences=diffs,equal_fields=equal)
  if arm=='baseline':
   with np.load(path/'test_fields.npz') as of,np.load(OUT/'runs'/f'baseline_seed{seed}'/'test_fields.npz') as nf:
    for k in ['target_index','target_raw','mask']:np.testing.assert_array_equal(of[k],nf[k])
    delta=np.abs(of['pred_raw'].astype(float)-nf['pred_raw'].astype(float));ev['prediction_max_abs_difference_K']=float(delta.max())
  else:
   assert all(equal.values());assert set(diffs)<= {'output_root','lambda_physics'}
  evidence.append(ev)
 rows.append(dict(seed=seed,old_baseline_test=b['test_rmse'],old_p0_0p1_val=p['best_val_rmse'],old_p0_0p1_test=p['test_rmse'],old_p0_improvement=100*(b['test_rmse']-p['test_rmse'])/b['test_rmse'],new_baseline_test=lookup['baseline',seed]['test_rmse'],new_p0_0p01_val=lookup['physics_only',seed]['val_rmse'],new_p0_0p01_test=lookup['physics_only',seed]['test_rmse'],new_p0_improvement=lookup['physics_only',seed]['improvement_percent']))
write_csv(OUT/'prior_comparison.csv',rows);(OUT/'prior_configuration_audit.json').write_text(json.dumps(evidence,indent=2)+'\n')
g={r['model']:r for r in results['groups']};primary=[b for b in results['bootstrap'] if b['block_days']==90 and b['seed_scope']=='fixed_3_seed_mean']
b=next(x for x in primary if x['comparison']=='physics_only - baseline')
lines=['# Interpretation — exploratory generalization, no retuning','', '## RQ1. Does Physics-only Validation improvement persist on Test?',f"Validation mean {g['baseline']['val_rmse_mean']:.6f} → {g['physics_only']['val_rmse_mean']:.6f} K. Test mean {g['baseline']['test_rmse_mean']:.6f} → {g['physics_only']['test_rmse_mean']:.6f} K; mean paired improvement {g['physics_only']['improvement_percent_mean']:+.4f}%. This is the observed direction in this period, not an independent confirmatory evaluation.",'', '## RQ2. Physics-only versus Auxiliary-only and Full',f"Test RMSE ranking: {', '.join(x['model']+'='+format(x['test_rmse_mean'],'.6f') for x in sorted(results['groups'],key=lambda z:z['test_rmse_mean']))}. Interpret all paired comparisons and CIs; Validation ranking does not determine Test ranking.",'', '## RQ3. Seed consistency',f"Physics-only improved {g['physics_only']['improved_seeds']}/3; Auxiliary-only {g['auxiliary_only']['improved_seeds']}/3; Full {g['full_pinn']['improved_seeds']}/3 versus Baseline. Seed-wise values are in seed_results.csv; n=3 is small.",'', '## RQ4. Uncertainty',f"Physics-only minus Baseline: {b['delta_rmse']:+.6f} K, primary90-day95% CI [{b['ci_low']:+.6f}, {b['ci_high']:+.6f}]; {b['interpretation']}. These are temporal sampling intervals conditional on three fitted seeds, not new independent training-seed observations. Zero-containing CI is neither proof of no effect nor equivalence. No multiple-comparison correction.",'', '## RQ5. Generalization gap','Smaller Test−Train gap is distinct from lower Test RMSE; higher Train error can shrink the gap without improving forecasts. All Train metrics use fixed best checkpoints, not online logs. This gap also reflects differences between selected historical training dates and the later Test distribution; it does not isolate overfitting causally.']+table(results['groups'],['model','train_rmse_mean','test_rmse_mean','test_train_gap_mean'])
lines+=['','## RQ6. MHW versus SST','CSI/POD higher is better; FAR lower is better. Describe detection tradeoffs rather than equating SST RMSE reduction with MHW improvement. Native MHW thresholds, reference dates and event logic are unchanged.']+table(results['groups'],['model','test_rmse_mean','csi_mean','pod_mean','far_mean'])
lines+=['','## Previous λ=.1 comparison','']+table(rows,['seed','old_p0_0p1_val','old_p0_0p1_test','old_p0_improvement','new_p0_0p01_val','new_p0_0p01_test','new_p0_improvement'])
lines+=['','The P0 .1 and .01 config audit finds identical predictor/head counts, initial shared state, manifests/statistics, splits and native training settings except output_root and lambda_physics. The old Baseline had no auxiliary heads; the new controlled Baseline has both inactive heads, so structural identity must not be claimed for that pair. prior_configuration_audit.json separately reports numerical prediction differences.','', 'Both physics coefficients follow the existing5-block warmup; .01/.1 are nominal coefficients, not necessarily the effective value at an early selected checkpoint. This compares complete weight schedules under the retained optimizer and checkpoint policy.','', 'λ exploration followed previously inspected Test results. The new evaluation is explicitly exploratory. No Test-driven weight choice, checkpoint replacement or structural adjustment is made. No assertion of optimality for .01 or .0001, nor independent confirmatory superiority.','', '## Scope and execution','12 existing checkpoints strictly loaded; every Validation reproduced before any new Test inference. No optimizer, backpropagation, new training or dataset change. Initial evaluation-only print-key exception was repaired before Test; initial records retained. Existing checkpoints verified by SHA before/after. See protocol.json, checkpoint_audit.json, analysis_tests.json, inference_status.json and final_integrity.json.']
lines += ['', '## Explicit RQ conclusions and robustness',
 f"RQ1: mean Test RMSE decreases by {g['baseline']['test_rmse_mean']-g['physics_only']['test_rmse_mean']:.6f}K for Physics-only. RQ2: Physics-only has lower point RMSE than Auxiliary-only, but Full has lower point RMSE than Physics-only by {g['physics_only']['test_rmse_mean']-g['full_pinn']['test_rmse_mean']:.6f}K. These are small within-period differences.",
 'RQ3/4: Physics-only seed42 and seed7 individual90-day CIs include zero; seed123 CI is entirely below zero. The fixed-three-seed mean CI is entirely below zero. Averaging fitted seeds does not create additional independent training runs.',
 f"RQ5: Physics-only Test−Train gap falls by {g['baseline']['test_train_gap_mean']-g['physics_only']['test_train_gap_mean']:.6f}K on average and decreases in all three seeds. This combines higher mean Train RMSE (+{g['physics_only']['train_rmse_mean']-g['baseline']['train_rmse_mean']:.6f}K) with lower Test RMSE; it is not a pure causal measure of overfitting.",
 'RQ6: Physics-only and Full reduce SST RMSE but lower CSI and POD versus Baseline. FAR is slightly lower on average. Thus SST improvement does not translate into improved MHW detection on the requested headline metrics.',
 '', 'Physics-only minus Baseline: predeclared block-length sensitivity (fixed3-seed mean):', ''] + table([v for v in results['bootstrap'] if v['comparison']=='physics_only - baseline' and v['seed_scope']=='fixed_3_seed_mean'], ['block_days','delta_rmse','ci_low','ci_high','ci_includes_zero'])
lines += ['', 'Physics-only daily spatial MSE autocorrelation at lag1 is .884–.933, lag7 .263–.440, lag30 .137–.231, and lag90 −.050 to −.018 (error_autocorrelation.csv). These diagnostics did not change the predeclared90-day primary block;30/180-day sensitivity preserves the mean-effect CI direction. Seasonal and nonstationary structure remains a limitation of time-block inference.', '', 'Every old versus new Baseline Test prediction is exactly identical (max absolute difference0K for all three seeds), despite the old model lacking the inactive heads. This numerical check does not remove the structural difference for future reuse accounting.']
(OUT/'interpretation.md').write_text('\n'.join(lines)+'\n')
print('prior comparison and six RQ interpretations written')
